begin;
with j as (select * from jsonb_to_recordset($law7d0038$[{"code_id":"BK_RF","article_number":"78.1","version_date":"1998-07-31","article_text":"(Наименование в редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 28.12.2013 № 418-ФЗ)\n\n1. В бюджетах бюджетной системы Российской Федерации предусматриваются субсидии бюджетным и автономным учреждениям на финансовое обеспечение выполнения ими государственного (муниципального)  задания,  в том числе в рамках исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере,  рассчитанные с учетом нормативных затрат на оказание ими государственных (муниципальных)  услуг физическим и (или)  юридическим лицам и нормативных затрат на содержание государственного (муниципального)  имущества. (В редакции федеральных законов от 07.05.2013 № 104-ФЗ,  от 13.07.2020 № 192-ФЗ)\n\nИз бюджетов бюджетной системы Российской Федерации могут предоставляться субсидии бюджетным и автономным учреждениям на иные цели,  в том числе на возмещение затрат,  а также недополученных доходов в связи с производством (реализацией)  товаров,  выполнением работ,  оказанием услуг по ценам (тарифам) ,  подлежащим в соответствии с законодательством Российской Федерации государственному регулированию. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nПорядок предоставления субсидий в соответствии с абзацем первым настоящего пункта из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местных бюджетов устанавливается соответственно нормативными правовыми актами  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  муниципальными правовыми актами местной администрации. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 02.07.2013 № 181-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nПорядок определения объема и условия предоставления субсидий в соответствии с абзацем вторым настоящего пункта (за исключением субсидий,  предоставляемых в соответствии со статьей 784 настоящего Кодекса)  из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местных бюджетов устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией или уполномоченными ими органами государственной власти (государственными органами) ,  органами местного самоуправления. Нормативные правовые акты (муниципальные правовые акты) ,  устанавливающие порядок определения объема и условия предоставления субсидий в соответствии с абзацем вторым настоящего пункта,  должны соответствовать общим требованиям,  установленным Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 02.07.2013 № 181-ФЗ)  (В редакции  федеральных законов от 27.12.2019 № 479-ФЗ,  от 13.07.2020 № 192-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nВ бюджете Федерального фонда обязательного медицинского страхования предусматриваются субсидии бюджетным и автономным учреждениям,  в отношении которых функции и полномочия учредителей осуществляют федеральные органы исполнительной власти,  на финансовое обеспечение выполнения этими учреждениями государственного задания на оказание высокотехнологичной медицинской помощи,  не включенной в базовую программу обязательного медицинского страхования. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 344-ФЗ)\n\nПредоставление предусмотренных настоящим пунктом субсидий,  за исключением субсидий из бюджета Федерального фонда обязательного медицинского страхования,  осуществляется в соответствии с соглашениями о предоставлении субсидий. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nПредоставление предусмотренных абзацем первым настоящего пункта субсидий,  за исключением субсидий из бюджета Федерального фонда обязательного медицинского страхования,  осуществляется в соответствии с соглашениями о предоставлении субсидии,  заключаемыми между органами государственной власти (органами местного самоуправления) ,  осуществляющими функции и полномочия учредителя,  и бюджетными или автономными учреждениями. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 345-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nСоглашения о предоставлении предусмотренных настоящим пунктом субсидий федеральным бюджетным или автономным учреждениям,  за исключением субсидий из бюджета Федерального фонда обязательного медицинского страхования,  заключаются в соответствии с типовой формой,  утверждаемой Министерством финансов Российской Федерации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 345-ФЗ)\n\n(Пункт в редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n2. В федеральном законе о федеральном бюджете могут предусматриваться субсидии иным некоммерческим организациям,  не являющимся государственными (муниципальными)  учреждениями,  государственными корпорациями (компаниями)  и публично-правовыми компаниями. (В редакции федеральных законов от 17.07.2009 № 145-ФЗ; от 08.05.2010 № 83-ФЗ; от 18.07.2017 № 178-ФЗ)\n\nВ законе субъекта Российской Федерации о бюджете субъекта Российской Федерации,  в решении представительного органа муниципального образования о местном бюджете могут предусматриваться субсидии иным некоммерческим организациям,  не являющимся государственными (муниципальными)  учреждениями. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\nСубсидии некоммерческим организациям,  указанным в абзацах первом и втором настоящего пункта,  предоставляются: (Дополнение абзацем - Федеральный закон от 19.12.2022 № 521-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nиз федерального бюджета - в случаях,  предусмотренных федеральным законом о федеральном бюджете,  в порядке,  установленном нормативным правовым актом  Правительства  Российской Федерации и принимаемыми в соответствии с ним решениями органов государственной власти (государственных органов)  и иных организаций,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств федерального бюджета; (Дополнение абзацем - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\nиз бюджета субъекта Российской Федерации - в случаях,  предусмотренных законом субъекта Российской Федерации о бюджете субъекта Российской Федерации,  в порядке,  установленном нормативными правовыми актами высшего исполнительного органа субъекта Российской Федерации или актами уполномоченных им органов государственной власти субъекта Российской Федерации,  за исключением случаев,  указанных в пункте 21 настоящей статьи; (Дополнение абзацем - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\nиз местного бюджета - в случаях,  предусмотренных решением представительного органа муниципального образования о местном бюджете,  в порядке,  установленном муниципальными правовыми актами местной администрации или актами уполномоченных ею органов местного самоуправления,  за исключением случаев,  указанных в пункте 21 настоящей статьи. (Дополнение абзацем - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 310-ФЗ)\n\n21. В случаях,  установленных законом субъекта Российской Федерации (муниципальным правовым актом представительного органа муниципального образования) ,  регулирующим бюджетные правоотношения,  субсидии,  указанные в пункте 2 настоящей статьи,  предоставляются из бюджета субъекта Российской Федерации (местного бюджета)  в соответствии с порядком,  установленным нормативным правовым актом  Правительства  Российской Федерации,  указанным в абзаце пятом пункта 2 настоящей статьи,  и принимаемыми в соответствии с ним решениями органов государственной власти субъектов Российской Федерации (органов местного самоуправления) ,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств бюджета субъекта Российской Федерации (главного распорядителя средств местного бюджета) . (Дополнение пунктом - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\n22. Нормативные правовые акты,  муниципальные правовые акты,  указанные в абзацах шестом и седьмом пункта 2 настоящей статьи,  должны соответствовать общим требованиям,  установленным Правительством Российской Федерации,  и содержать положения об осуществлении в отношении получателей субсидий и лиц,  указанных в пункте 3 настоящей статьи,  проверок главным распорядителем (распорядителем)  бюджетных средств,  предоставляющим субсидии,  соблюдения ими порядка и условий предоставления субсидий,  в том числе в части достижения результатов их предоставления,  а также проверок органами государственного (муниципального)  финансового контроля в соответствии со статьями 2681 и 2692 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 19.12.2022 № 521-ФЗ)\n\n3. При предоставлении субсидий,  указанных в пунктах 2 и 4 настоящей статьи,  обязательными условиями их предоставления,  включаемыми в договоры (соглашения)  о предоставлении субсидий и (или)  в нормативные правовые акты,  муниципальные правовые акты,  регулирующие порядок их предоставления,  и договоры (соглашения) ,  заключенные в целях исполнения обязательств по данным договорам (соглашениям) ,  являются согласие получателей субсидий и лиц,  являющихся поставщиками (подрядчиками,  исполнителями)  по договорам (соглашениям) ,  заключенным в целях исполнения обязательств по договорам (соглашениям)  о предоставлении субсидий на финансовое обеспечение затрат получателей субсидий,  на осуществление главным распорядителем (распорядителем)  бюджетных средств,  предоставляющим субсидии,  и органами государственного (муниципального)  финансового контроля проверок,  предусмотренных пунктом 22 настоящей статьи,  и запрет приобретения за счет средств,  предоставленных в целях финансового обеспечения затрат получателей субсидий,  иностранной валюты,  за исключением операций,  осуществляемых в соответствии с валютным законодательством Российской Федерации при закупке (поставке)  высокотехнологичного импортного оборудования,  сырья и комплектующих изделий,  а также иных операций в случаях,  определенных нормативными правовыми актами,  муниципальными правовыми актами,  решениями Президента Российской Федерации,   Правительства  Российской Федерации,  высшего должностного лица субъекта Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации,  регулирующими порядок предоставления субсидий,  или решениями органов государственной власти (государственных органов)  и иных организаций,  органов местного самоуправления,  осуществляющих в соответствии с настоящим Кодексом полномочия главных распорядителей бюджетных средств,  предусмотренных абзацем пятым пункта 2 и пунктом 21 настоящей статьи. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции  федеральных законов от 15.02.2016 № 23-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 28.12.2017 № 434-ФЗ,  от 27.12.2018 № 504-ФЗ,  от 31.07.2020 № 263-ФЗ,  от 29.11.2021 № 384-ФЗ,  от 19.12.2022 № 521-ФЗ,  от 14.04.2023 № 128-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\n4. В законе (решении)  о бюджете могут предусматриваться бюджетные ассигнования на предоставление,  в том числе в соответствии с решением Президента Российской Федерации,  некоммерческим организациям,  не являющимся казенными учреждениями,  грантов в форме субсидий,  в том числе предоставляемых федеральными органами исполнительной власти,  исполнительными органами субъектов Российской Федерации,  органами местной администрации по результатам проводимых ими отборов бюджетным и автономным учреждениям,  включая учреждения,  в отношении которых указанные органы не осуществляют функции и полномочия учредителя.\n\nГранты в форме субсидий,  указанные в настоящем пункте,  за исключением грантов,  порядок предоставления которых определен решением Президента Российской Федерации,  предоставляются:\n\nиз федерального бюджета - в соответствии с порядком,  указанным в абзаце пятом пункта 2 настоящей статьи;\n\nиз бюджета субъекта Российской Федерации - в соответствии с порядком,  указанным в абзаце шестом пункта 2 или пункте 21 настоящей статьи;\n\nиз местного бюджета - в соответствии с порядком,  указанным в абзаце седьмом пункта 2 или пункте 21 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2013 № 181-ФЗ)  (В редакции  Федерального закона от 19.12.2022 № 521-ФЗ)\n\n5. В договоры бюджетных и автономных учреждений о поставке товаров,  выполнении работ,  оказании услуг,  подлежащие оплате за счет субсидий,  указанных в пункте 1 настоящей статьи,  включается условие о возможности изменения по соглашению сторон размера и (или)  сроков оплаты и (или)  объема товаров,  работ,  услуг в случае уменьшения в соответствии с настоящим Кодексом получателю бюджетных средств,  предоставляющему субсидии,  ранее доведенных в установленном порядке лимитов бюджетных обязательств на предоставление субсидии.\n\nВ случае признания в соответствии с настоящим Кодексом утратившими силу положений закона (решения)  о бюджете на текущий финансовый год и плановый период в части,  относящейся к плановому периоду,  бюджетное или автономное учреждение вправе не принимать решение о расторжении предусмотренных настоящим пунктом договоров,  подлежащих оплате в плановом периоде,  при условии заключения дополнительных соглашений к указанным договорам,  определяющих условия их исполнения в плановом периоде.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 23-ФЗ)\n\n6. Договоры (соглашения)  о предоставлении субсидий,  предусмотренных пунктами 2 и 4 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета и дополнительные соглашения к указанным договорам (соглашениям) ,  предусматривающие внесение в них изменений или их расторжение,  заключаются в соответствии с типовыми формами,  утверждаемыми соответственно Министерством финансов Российской Федерации,  финансовым органом субъекта Российской Федерации,  финансовым органом муниципального образования. (Дополнение пунктом - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n7. Субсидии в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере некоммерческим организациям,  указанным в пункте 2 настоящей статьи,  являющимся исполнителями таких услуг,  предоставляются из бюджетов бюджетной системы Российской Федерации в соответствии со статьей 784 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\n8. Заключение договоров (соглашений)  о предоставлении субсидий,  предусмотренных абзацем вторым пункта 1,  пунктами 2 и 4 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в случаях,  предусмотренных соответственно решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации,  принимаемыми в определяемом ими порядке. (Дополнение пунктом - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n9. Правительство Российской Федерации устанавливает особенности применения указанных в пункте 22 настоящей статьи общих требований к нормативным правовым актам субъектов Российской Федерации,  в бюджете которых расчетная доля межбюджетных трансфертов из федерального бюджета (за исключением субвенций)  в течение двух из трех последних отчетных финансовых лет не превышала 20 процентов объема собственных доходов консолидированного бюджета субъекта Российской Федерации,  которые регулируют предоставление субсидий иным некоммерческим организациям,  не являющимся государственными (муниципальными)  учреждениями,  а также грантов в форме субсидий некоммерческим организациям,  не являющимся казенными учреждениями. (Дополнение пунктом - Федеральный закон от 28.06.2022 № 227-ФЗ)  (В редакции  Федерального закона от 19.12.2022 № 521-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 78.1. Предоставление субсидий (кроме субсидий на осуществление капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность)  некоммерческим организациям,  не являющимся казенными учреждениями","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b0cbc28f25506c4802232102a9dd69d6476b937ffef9813af5f0bc91873e81af"},{"code_id":"BK_RF","article_number":"78.2","version_date":"1998-07-31","article_text":"1. В бюджетах бюджетной системы Российской Федерации бюджетным и автономным учреждениям,  государственным (муниципальным)  унитарным предприятиям могут предусматриваться субсидии на осуществление указанными учреждениями и предприятиями капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недв\n\nются в случаях,  предусмотренных соответственно решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации,  принимаемыми в определяемом ими порядке. (В редакции  федеральных законов от 27.12.2018 № 504-ФЗ,  от 02.08.2019 № 295-ФЗ,  от 15.10.2020 № 327-ФЗ,  от 30.04.2021 № 108-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nЗаключение договора (соглашения)  о предоставлении субсидии юридическому лицу,  являющемуся стороной соглашения о защите и поощрении капиталовложений,  заключенного в порядке,  установленном Федеральным законом от 1 апреля 2020 года № 69-ФЗ \"О защите и поощрении капиталовложений в Российской Федерации\",  на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в пределах сроков и объемов возмещения затрат,  определяемых в соответствии с указанным Федеральным законом. (Дополнение абзацем - Федеральный закон от 30.04.2021 № 108-ФЗ)\n\nДоговоры (соглашения)  о предоставлении субсидий,  указанные в абзацах первом и втором настоящего пункта,  и дополнительные соглашения к указанным договорам (соглашениям) ,  предусматривающие внесение в них изменений или их расторжение,  заключаются в соответствии с типовыми формами,  утверждаемыми соответственно Министерством финансов Российской Федерации,  финансовым органом субъекта Российской Федерации,  финансовым органом муниципального образования. (В редакции федеральных законов от 27.12.2018 № 504-ФЗ,  от 30.04.2021 № 108-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n10. Субсидии в целях финансового обеспечения исполнения государственного (муниципального)  социального заказа на оказание государственных (муниципальных)  услуг в социальной сфере юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг,  являющимся исполнителями таких услуг,  предоставляются из бюджетов бюджетной системы Российской Федерации в соответствии со статьей 784 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 13.07.2020 № 192-ФЗ)\n\n11. Правительство Российской Федерации устанавливает особенности применения указанных в пункте 3 настоящей статьи общих требований к нормативным правовым актам субъектов Российской Федерации,  в бюджете которых расчетная доля межбюджетных трансфертов из федерального бюджета (за исключением субвенций)  в течение двух из трех последних отчетных финансовых лет не превышала 20 процентов объема собственных доходов консолидированного бюджета субъекта Российской Федерации,  которые регулируют предоставление субсидий,  в том числе грантов в форме субсидий,  юридическим лицам (за исключением субсидий государственным (муниципальным)  учреждениям) ,  индивидуальным предпринимателям,  а также физическим лицам - производителям товаров,  работ,  услуг. (Дополнение пунктом - Федеральный закон от 28.06.2022 № 227-ФЗ)  (В редакции  Федерального закона от 19.12.2022 № 521-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 78.2. Предоставление субсидий на осуществление капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности и приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd04cc913e2d7fe6916cfab2c98f1f125f33b884e8a22121c8bc8ffefe05c8b5"}]$law7d0038$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
